import re,os,collections
def mod2path(m): return m.replace('.','/')+'.lean'
def path2mod(p): return p[:-5].replace('/','.')
imports={}
for root,d,fs in os.walk('AlgebraicJacobian'):
    for f in fs:
        if f.endswith('.lean'):
            p=os.path.join(root,f)
            ms=re.findall(r'^import\s+(\S+)',open(p).read(),re.M)
            imports[path2mod(p)]=ms
imports['AlgebraicJacobian']=re.findall(r'^import\s+(\S+)',open('AlgebraicJacobian.lean').read(),re.M)
seen=set();stack=['AlgebraicJacobian']
while stack:
    m=stack.pop()
    if m in seen: continue
    seen.add(m)
    for x in imports.get(m,[]):
        if x.startswith('AlgebraicJacobian') and x not in seen: stack.append(x)
files=set(imports)-{'AlgebraicJacobian'}
reach=seen&files
print('files under AlgebraicJacobian/:',len(files))
print('reachable:',len(reach))
print('unrooted:',len(files-reach))
